#!/usr/bin/env bash
# Creates all backlog items as GitHub issues and adds them to the project.
# Prerequisites: install GitHub CLI, run:  gh auth login   then   gh auth refresh -s project
# Edit the usernames below, then run:  bash create_backlog_issues.sh
set -e
REPO="sravya-cloud/online_examination_portal"
OWNER="sravya-cloud"
PROJECT_NUMBER=3
MEMBER1="sravya-cloud"
MEMBER2="nehas005"
MEMBER3="manasvidr"
MEMBER4="NehaaJ05"
for l in sprint-1 sprint-2 functional non-functional; do gh label create "$l" --repo "$REPO" 2>/dev/null || true; done
for p in 1 2 3 5; do gh label create "sp-$p" --repo "$REPO" 2>/dev/null || true; done
add() { # id title body sprint points assignee type
  url=$(gh issue create --repo "$REPO" --title "$1: $2" --body "$3" --assignee "$6" --label "sprint-$4,sp-$5,$7")
  gh project item-add $PROJECT_NUMBER --owner "$OWNER" --url "$url"
  echo "created $1"
}
add "FR-01" "Student login" $'**Story:** As a student, I want to log in with valid credentials so that I can access my exams.\n\n**Acceptance criteria:** Valid credentials open the student dashboard; invalid ones show a clear error (VAL-F01).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Authentication' 1 3 "$MEMBER1" functional
add "FR-02" "Teacher login" $'**Story:** As a teacher, I want to log in with valid credentials so that I can manage questions and exams.\n\n**Acceptance criteria:** Valid credentials open the teacher dashboard; invalid ones are rejected (VAL-F01).\n\n**Story Points:** 2  |  **Sprint:** 1  |  **Area:** Authentication' 1 2 "$MEMBER1" functional
add "FR-22" "Administrator login" $'**Story:** As an administrator, I want to log in with valid credentials before using admin functions.\n\n**Acceptance criteria:** Admin dashboard is reachable only after successful login (VAL-F20).\n\n**Story Points:** 2  |  **Sprint:** 1  |  **Area:** Authentication' 1 2 "$MEMBER1" functional
add "FR-05" "Upload questions to question bank" $'**Story:** As a teacher, I want to upload questions to the question bank so that exams can use them.\n\n**Acceptance criteria:** Objective questions with options and correct answer are saved and listed (VAL-F02).\n\n**Story Points:** 5  |  **Sprint:** 1  |  **Area:** Question Bank' 1 5 "$MEMBER2" functional
add "FR-06" "Assign difficulty level to questions" $'**Story:** As a teacher, I want to set a difficulty level on each question.\n\n**Acceptance criteria:** Every saved question stores a difficulty value that can be viewed (VAL-F03).\n\n**Story Points:** 2  |  **Sprint:** 1  |  **Area:** Question Bank' 1 2 "$MEMBER2" functional
add "FR-07" "Edit or remove questions before publishing" $'**Story:** As a teacher, I want to edit or delete questions until the exam is published.\n\n**Acceptance criteria:** Edit/delete works before publish and is blocked after publish (VAL-F13).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Question Bank' 1 3 "$MEMBER2" functional
add "FR-04" "Create examinations" $'**Story:** As a teacher, I want to create an exam using configured settings.\n\n**Acceptance criteria:** An exam record is created with title, question count and pool selection (VAL-F04).\n\n**Story Points:** 5  |  **Sprint:** 1  |  **Area:** Exam Configuration' 1 5 "$MEMBER2" functional
add "FR-08" "Configure exam duration and availability period" $'**Story:** As a teacher, I want to set the exam duration and availability window.\n\n**Acceptance criteria:** Duration, start and end times are saved and applied to the exam (VAL-F04).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Exam Configuration' 1 3 "$MEMBER2" functional
add "FR-21" "Display available examinations to students" $'**Story:** As a student, I want to see exams that are currently available to me.\n\n**Acceptance criteria:** Only exams inside their availability window are listed (VAL-F11).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 3 "$MEMBER3" functional
add "FR-09" "Random selection of questions from pool" $'**Story:** As the system, I randomly pick the configured number of questions when an exam is initialized.\n\n**Acceptance criteria:** Exactly N questions are chosen at random from the pool (VAL-F05).\n\n**Story Points:** 5  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 5 "$MEMBER3" functional
add "FR-10" "Same question set for all students" $'**Story:** As a teacher, I want every student on the same exam to get the same selected questions.\n\n**Acceptance criteria:** Question set is fixed once per exam and identical for all attempts (VAL-F05).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 3 "$MEMBER3" functional
add "FR-11" "Shuffle question order" $'**Story:** As a student, I see the selected questions in shuffled order.\n\n**Acceptance criteria:** Order differs between attempts while the set stays the same (VAL-F06).\n\n**Story Points:** 2  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 2 "$MEMBER3" functional
add "FR-12" "Display questions of active attempt" $'**Story:** As a student, I want to see the questions of my active attempt.\n\n**Acceptance criteria:** Only the active attempt\'s questions are shown (VAL-F06).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 3 "$MEMBER3" functional
add "FR-13" "Select and save answers" $'**Story:** As a student, I want to select, save and change answers before submitting.\n\n**Acceptance criteria:** Answers persist and can be revisited and changed until submission (VAL-F12).\n\n**Story Points:** 5  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 5 "$MEMBER3" functional
add "FR-15" "Manual submission" $'**Story:** As a student, I want to submit my exam before time runs out.\n\n**Acceptance criteria:** Submit locks the attempt and stores the answers (VAL-F07).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** Exam Attempt' 1 3 "$MEMBER3" functional
add "NFR-01" "Security: authenticated access and role-based authorization" $'**Story:** The system requires login for protected functions and enforces Student/Teacher/Administrator roles (covers SEC-01 to SEC-04, SEC-07, SEC-09, SEC-10).\n\n**Acceptance criteria:** Unauthenticated or wrong-role access is denied; sessions expire; errors expose no internals (VAL-N01).\n\n**Story Points:** 3  |  **Sprint:** 1  |  **Area:** NFR' 1 3 "$MEMBER1" non-functional
add "NFR-07" "Maintainability: modular components" $'**Story:** Code is split into modules with documented interfaces.\n\n**Acceptance criteria:** Modules match the SAD; one module can be changed/tested independently (VAL-N07).\n\n**Story Points:** 1  |  **Sprint:** 1  |  **Area:** NFR' 1 1 "$MEMBER4" non-functional
add "NFR-08" "Compatibility: current desktop browsers" $'**Story:** The web portal works on current major desktop browsers.\n\n**Acceptance criteria:** Core flows work on latest Chrome, Edge and Firefox (VAL-N08).\n\n**Story Points:** 1  |  **Sprint:** 1  |  **Area:** NFR' 1 1 "$MEMBER4" non-functional
add "NFR-09" "Testability: validation per requirement" $'**Story:** Each requirement has a test method with observable acceptance criteria.\n\n**Acceptance criteria:** Test cases exist for each FR/NFR per the Test Plan and RTM (VAL-N09).\n\n**Story Points:** 2  |  **Sprint:** 1  |  **Area:** NFR' 1 2 "$MEMBER4" non-functional
add "FR-14" "Auto-submit on duration expiry" $'**Story:** As a student, my attempt is submitted automatically when time ends.\n\n**Acceptance criteria:** Attempt auto-submits at expiry with saved answers intact (VAL-F07).\n\n**Story Points:** 5  |  **Sprint:** 2  |  **Area:** Exam Attempt' 2 5 "$MEMBER3" functional
add "FR-16" "Automatic evaluation of objective questions" $'**Story:** As the system, I evaluate answers against configured correct answers.\n\n**Acceptance criteria:** Each answer is marked right/wrong automatically (VAL-F08).\n\n**Story Points:** 5  |  **Sprint:** 2  |  **Area:** Evaluation & Results' 2 5 "$MEMBER4" functional
add "FR-17" "Calculate exam score" $'**Story:** As the system, I calculate the score from evaluated answers.\n\n**Acceptance criteria:** Score equals the sum of correct answers per exam rules (VAL-F08).\n\n**Story Points:** 3  |  **Sprint:** 2  |  **Area:** Evaluation & Results' 2 3 "$MEMBER4" functional
add "FR-18" "Securely store attempts and answers" $'**Story:** As the system, I store attempts and submitted answers securely.\n\n**Acceptance criteria:** Attempts/answers are persisted and cannot be modified by unauthorized users (VAL-S11; SEC-05).\n\n**Story Points:** 5  |  **Sprint:** 2  |  **Area:** Evaluation & Results' 2 5 "$MEMBER4" functional
add "FR-19" "Automatic result release at configured time" $'**Story:** As a student, I see my result when the configured release time arrives.\n\n**Acceptance criteria:** Results are hidden before release time and visible after it (VAL-F09, VAL-F10; SEC-06).\n\n**Story Points:** 5  |  **Sprint:** 2  |  **Area:** Evaluation & Results' 2 5 "$MEMBER4" functional
add "FR-20" "View examination reports" $'**Story:** As a teacher or administrator, I want to view exam reports.\n\n**Acceptance criteria:** Authorized roles can open reports; students cannot (VAL-F14).\n\n**Story Points:** 5  |  **Sprint:** 2  |  **Area:** Reports' 2 5 "$MEMBER4" functional
add "FR-03" "Admin: manage users and roles" $'**Story:** As an administrator, I want to manage users and assign roles.\n\n**Acceptance criteria:** Admin can create/update/disable users and set roles (VAL-F15, VAL-F16, VAL-F18).\n\n**Story Points:** 5  |  **Sprint:** 2  |  **Area:** Administration' 2 5 "$MEMBER1" functional
add "FR-23" "Admin: manage system-level settings" $'**Story:** As an administrator, I want to manage approved system settings.\n\n**Acceptance criteria:** Authorized admin can view and change approved settings (VAL-F21).\n\n**Story Points:** 3  |  **Sprint:** 2  |  **Area:** Administration' 2 3 "$MEMBER1" functional
add "FR-24" "Admin: manage access permissions by role" $'**Story:** As an administrator, I want to manage access permissions per role.\n\n**Acceptance criteria:** Permission changes take effect for the affected roles (VAL-F22).\n\n**Story Points:** 3  |  **Sprint:** 2  |  **Area:** Administration' 2 3 "$MEMBER1" functional
add "NFR-02" "Reliability: no loss of submitted data" $'**Story:** Submitted answers and attempt data are not lost in normal operation.\n\n**Acceptance criteria:** Submitted data survives restart and normal use (VAL-N02).\n\n**Story Points:** 2  |  **Sprint:** 2  |  **Area:** NFR' 2 2 "$MEMBER4" non-functional
add "NFR-03" "Performance: common actions within 3 seconds" $'**Story:** Common user actions respond within 3 seconds under normal load.\n\n**Acceptance criteria:** Measured response for common actions is 3 s or less (VAL-N03).\n\n**Story Points:** 2  |  **Sprint:** 2  |  **Area:** NFR' 2 2 "$MEMBER2" non-functional
add "NFR-04" "Availability during exam window" $'**Story:** The system stays available throughout an exam\'s availability period.\n\n**Acceptance criteria:** No unplanned downtime during a test exam window (VAL-N04).\n\n**Story Points:** 1  |  **Sprint:** 2  |  **Area:** NFR' 2 1 "$MEMBER2" non-functional
add "NFR-05" "Usability: clear navigation and feedback" $'**Story:** Navigation, instructions and feedback messages are clear.\n\n**Acceptance criteria:** Major actions give understandable feedback (VAL-N05).\n\n**Story Points:** 2  |  **Sprint:** 2  |  **Area:** NFR' 2 2 "$MEMBER3" non-functional
add "NFR-06" "Learnability: first-time student finishes within 5 minutes" $'**Story:** A first-time student can start and submit an exam within 5 minutes unaided.\n\n**Acceptance criteria:** Timed trial with a new user succeeds in 5 min or less (VAL-N06).\n\n**Story Points:** 1  |  **Sprint:** 2  |  **Area:** NFR' 2 1 "$MEMBER3" non-functional
add "NFR-10" "Scalability: more concurrent users" $'**Story:** The system handles more concurrent exam users without workflow change.\n\n**Acceptance criteria:** Load test with increased users keeps the same workflow (VAL-N10).\n\n**Story Points:** 1  |  **Sprint:** 2  |  **Area:** NFR' 2 1 "$MEMBER2" non-functional
add "NFR-11" "Data integrity" $'**Story:** Questions, answers, attempts, scores and results stay consistent.\n\n**Acceptance criteria:** No orphaned or inconsistent records after full exam flow (VAL-N11).\n\n**Story Points:** 2  |  **Sprint:** 2  |  **Area:** NFR' 2 2 "$MEMBER4" non-functional
add "NFR-12" "Auditability: log important actions" $'**Story:** Important admin and exam actions are logged (covers SEC-08).\n\n**Acceptance criteria:** Admin and exam actions appear in an audit log (VAL-N12).\n\n**Story Points:** 3  |  **Sprint:** 2  |  **Area:** NFR' 2 3 "$MEMBER1" non-functional
